def build_tags_extraction_guide(plan_tags: list[str]) -> str:
    """构建标签提取指南"""
    guides = []
    for tag in plan_tags:
        if tag in PLAN_TAGS_CONFIG:
            config = PLAN_TAGS_CONFIG[tag]
            guides.append(f"### {tag}\n- 关注点：{', '.join(config['question_focus'])}")
    return "\n\n".join(guides)


def build_tags_question_guide(plan_tags: list[str]) -> str:
    """构建标签问题生成指南"""
    guides = []
    for tag in plan_tags:
        if tag in PLAN_TAGS_CONFIG:
            config = PLAN_TAGS_CONFIG[tag]
            guides.append(
                f"### {tag}\n"
                f"- 描述：{config['description']}\n"
                f"- 问题方向：{', '.join(config['question_focus'])}"
            )
    return "\n\n".join(guides)


def build_tags_generation_guide(plan_tags: list[str]) -> str:
    """构建标签内容生成指南"""
    guides = []
    for tag in plan_tags:
        if tag in PLAN_TAGS_CONFIG:
            config = PLAN_TAGS_CONFIG[tag]
            guides.append(
                f"### {tag}\n"
                f"- 撰写要求：{config['generation_guide']}\n"
                f"- 必含要素：{', '.join(config['key_elements'])}"
            )
    return "\n\n".join(guides)


def get_polish_rule_description(rule: str) -> str:
    """获取润色规则描述"""
    return POLISH_RULES_CONFIG.get(rule, POLISH_RULES_CONFIG["default"])

"""
教案生成API路由
"""
import sys
import traceback
from datetime import datetime

from fastapi import APIRouter, HTTPException
from fastapi.responses import StreamingResponse
from loguru import logger

from models import (
    QuestionGenerateRequest,
    LessonGenerateRequest,
    ParagraphPolishRequest,
    APIResponse,
)
from services import (
    generate_questions,
    generate_lesson,
    generate_lesson_stream,
    polish_paragraph,
    polish_paragraph_stream,
)

router = APIRouter(prefix="/api/v1/lesson-plan", tags=["lesson-plan"])


@router.post("/questions/generate", response_model=APIResponse)
async def api_generate_questions(request: QuestionGenerateRequest):
    """生成引导性问题接口"""
    try:
        result = await generate_questions(request)
        return APIResponse(
            code=200,
            message="success",
            data=result.model_dump(),
            timestamp=int(datetime.now().timestamp()),
        )
    except ValueError as e:
        logger.warning(f"Invalid request: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
        logger.error(f"Question generation API error: {error_message}")
        raise HTTPException(status_code=500, detail="Internal server error")


@router.post("/lesson/generate")
async def api_generate_lesson(request: LessonGenerateRequest):
    """生成教案接口（支持流式）"""
    try:
        if request.stream:
            # 流式响应
            return StreamingResponse(
                generate_lesson_stream(request),
                media_type="text/event-stream",
                headers={
                    "Cache-Control": "no-cache",
                    "Connection": "keep-alive",
                },
            )
        else:
            # 非流式响应
            result = await generate_lesson(request)
            return APIResponse(
                code=200,
                message="success",
                data=result.model_dump(),
                timestamp=int(datetime.now().timestamp()),
            )
    except ValueError as e:
        logger.warning(f"Invalid request: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
        logger.error(f"Lesson generation API error: {error_message}")
        raise HTTPException(status_code=500, detail="Internal server error")


